                    if m.take_damage(10):
                        self.monsters.remove(m)
                        self.particles.emit(m.x, m.y, m.color, count=30, lifetime=40)

        for m in self.monsters:
            m.update()

    elif self.game_mode == 'platformer':
        self.player.update(keys, self.floor_y)
        if beat:
