def update(self, keys_pressed):
    hit_window = 40
    multiplier = 2 if self.rift_active else 1

    # Update rift timer
    if self.rift_active:
        self.rift_timer -= 1
        if self.rift_timer <= 0:
            self.rift_active = False

    for note in self.notes[:]:
        if not note.hit and not note.missed:
            note.y += note.speed

            # Check if in hit zone and key pressed
            if abs(note.y - self.hit_zone_y) < hit_window:
                if self.LANE_KEYS[note.lane] in keys_pressed:
                    note.hit = True
                    points = 100 * (1 + self.combo // 10) * multiplier
                    self.score += points
                    self.combo += 1
                    self.max_combo = max(self.max_combo, self.combo)

                    # Build rift charge
                    self.rift_charge = min(self.rift_max, self.rift_charge + 5)

                    self.hit_effects.append({
                        'x': self.start_x + note.lane * self.lane_width + self.lane_width // 2,
                        'y': self.hit_zone_y,
                        'timer': 20,
                        'color': COLORS['neon_green'] if self.rift_active else self.LANE_COLORS[note.lane]
                    })

